-          <StudioShell />
-          <FirstRunWizard />
-        </OnboardingProvider>
-      </StudioProvider>
+      <UpdateProvider>
+        <StudioProvider>
+          <StudioRuntimeProvider>
+            <OnboardingProvider>
+              <StudioShell />
+              <FirstRunWizard />
+            </OnboardingProvider>
+          </StudioRuntimeProvider>
+        </StudioProvider>
+      </UpdateProvider>
     </ErrorBoundary>
   );
 }

