   gap: 12px;
   align-items: center;
   padding: 13px 2px;
   border-bottom: 1px solid var(--line);
 }

 .wizard-check__dot {
   width: 7px;
   height: 7px;
   border-radius: 50%;
   background: var(--faint);
 }

 .wizard-check--ok .wizard-check__dot {
   background: var(--green);
   box-shadow: 0 0 8px rgba(74, 222, 128, 0.45);
 }

 .wizard-check--warn .wizard-check__dot {
   background: var(--amber);
   box-shadow: 0 0 8px rgba(240, 179, 74, 0.35);
 }

 .wizard-check--pending .wizard-check__dot {
   background: var(--accent);
   animation: wizard-pulse 1.2s infinite ease-in-out;
 }

 .wizard-check__label {
   display: block;
   font-size: 0.9rem;
   font-weight: 500;
   color: var(--text);
 }

 .wizard-check__detail {
   display: block;
   margin-top: 1px;
   font-size: 0.78rem;
   color: var(--muted);
 }

 .wizard-check__state {
   font-size: 0.78rem;
   color: var(--muted);
 }

 .wizard-check--ok .wizard-check__state {
   color: var(--green);
 }

 .wizard-check--warn .wizard-check__state {
   color: var(--amber);
 }

 .wizard-config {
   margin-bottom: 10px;
   padding: 16px;
   border-radius: 12px;
   border: 1px solid rgba(240, 179, 74, 0.18);
   background: rgba(240, 179, 74, 0.045);
 }

 .wizard-config__hint {
   margin: 0 0 14px;
   font-size: 0.84rem;
   line-height: 1.55;
   color: var(--muted);
 }

 .wizard-config__message {
   margin: 0 0 12px;
   font-size: 0.8rem;
   color: var(--amber);
 }

 .wizard-config__grid {
   display: grid;
   grid-template-columns: 1fr 1fr;
   gap: 0 12px;
 }

 .wizard-config__key {
   grid-column: 1 / -1;
 }

 .wizard-config__actions {
   display: flex;
   flex-wrap: wrap;
   align-items: center;
   gap: 8px;
 }

 .wizard-config__status {
   font-size: 0.78rem;
   color: var(--muted);
 }

 /* ------------------------------------------------------------------ */
 /* Step 4 — first move                                                */
 /* ------------------------------------------------------------------ */

 .wizard-launch {
   display: grid;
   gap: 16px;
 }

 .wizard-choice {
   display: flex;
   align-items: center;
   gap: 12px;
 }

 .wizard-choice__title {
   display: block;
   font-size: 0.95rem;
   font-weight: 600;
   color: var(--text);
 }

 .wizard-choice__result {
   display: block;
   margin-top: 2px;
   font-size: 0.83rem;
   color: var(--muted);
 }

 .wizard-destination {
   padding: 14px 18px;
   border-left: 2px solid rgba(139, 140, 248, 0.7);
   border-radius: 0 10px 10px 0;
   background: rgba(139, 140, 248, 0.07);
 }

 .wizard-destination__label {
   margin: 0 0 4px;
   font-size: 0.68rem;
   font-weight: 600;
   letter-spacing: 0.16em;
   text-transform: uppercase;
   color: var(--faint);
 }

 .wizard-destination__detail {
   margin: 0;
   font-size: 0.9rem;
   line-height: 1.55;
   color: var(--text);
 }

 /* ------------------------------------------------------------------ */
 /* Footer                                                             */
 /* ------------------------------------------------------------------ */

 .wizard-footer {
   position: relative;
   z-index: 1;
   display: flex;
   align-items: center;
   justify-content: space-between;
   gap: 12px;
   padding: 18px 30px 22px;
   border-top: 1px solid var(--line);
   background: rgba(6, 7, 10, 0.4);
 }

+.wizard-footer__skips {
+  display: flex;
+  flex-wrap: wrap;
+  gap: 12px;
+}
+
 .wizard-footer__actions {
   display: flex;
   flex-wrap: wrap;
   justify-content: flex-end;
   gap: 8px;
 }

 .wizard-panel .button {
   min-height: 40px;
   padding: 9px 15px;
 }

 .wizard-text-button {
   min-height: 32px;
   padding: 6px 6px;
   border: none;
   border-radius: 6px;
   background: none;
   color: var(--muted);
   font-size: 0.8rem;
   cursor: pointer;
 }

 .wizard-text-button:hover {
   color: var(--text);
 }

 .wizard-button--primary {
   border-color: rgba(139, 140, 248, 0.55);
   background: linear-gradient(180deg, #6366f1, #4f46e5);
   font-weight: 600;
   box-shadow:
     0 6px 18px -8px rgba(79, 70, 229, 0.8),
     inset 0 1px 0 rgba(255, 255, 255, 0.15);
 }

 .wizard-button--primary:hover:not(:disabled) {
   background: linear-gradient(180deg, #7275f4, #5b52ea);
 }

 .wizard-button--primary:disabled {
   border-color: var(--line);
   background: rgba(99, 102, 241, 0.18);
   box-shadow: none;
 }

 /* ------------------------------------------------------------------ */
 /* Motion                                                             */
 /* ------------------------------------------------------------------ */

 @keyframes wizard-fade {
   from {
     opacity: 0;
   }
   to {
     opacity: 1;
   }
 }

 @keyframes wizard-enter {
   from {
     opacity: 0;
     transform: translateY(14px) scale(0.985);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes wizard-rise {
   from {
     opacity: 0;
     transform: translateY(8px);
   }
   to {
     opacity: 1;
     transform: none;
   }
 }

 @keyframes wizard-pulse {
   0%,
   100% {
     opacity: 0.35;
   }
   50% {
     opacity: 1;
   }
 }

 @media (prefers-reduced-motion: reduce) {
   .wizard-backdrop,
   .wizard-panel,
   .wizard-body,
   .wizard-check--pending .wizard-check__dot {
     animation: none !important;
     transition: none !important;
   }
 }

 /* ------------------------------------------------------------------ */
 /* Small screens                                                      */
 /* ------------------------------------------------------------------ */

 @media (max-width: 640px) {
   .wizard-backdrop {
     align-items: stretch;
     padding: 0;
