   }

   .wizard-goals {
     grid-template-columns: 1fr;
   }

   .wizard-config__grid {
     grid-template-columns: 1fr;
   }

   .wizard-panel .button {
     min-height: 44px;
   }

   .wizard-text-button {
     min-height: 44px;
   }
