 }

 .ui-action:active {
   transform: translateY(1px);
 }

 .ui-action:disabled {
   opacity: 0.5;
   cursor: not-allowed;
   transform: none;
 }

 /* Tables */
 .ui-table-wrap {
   overflow-x: auto;
 }

 .ui-table {
   width: 100%;
   border-collapse: collapse;
   font-size: 0.86rem;
 }

 .ui-table th {
   padding: 0 0 6px;
   border-bottom: 1px solid var(--studio-border);
   text-align: left;
   font-size: 0.66rem;
   font-weight: 600;
