 }

 .ui-table td:first-child {
   padding-right: 12px;
 }

 .ui-table td:last-child {
   text-align: right;
   white-space: nowrap;
 }

 .ui-table .ui-card__id {
   display: block;
 }

 .ui-table__statement {
   display: block;
