+def rank_outcomes(outcomes: list[Outcome]) -> list[Outcome]:
+    """Rank outcomes by opportunity score, highest first, unscored last."""
+    return sorted(
+        outcomes,
+        key=lambda outcome: (
+            outcome.opportunity_score is None,
+            -(outcome.opportunity_score or 0.0),
+        ),
+    )
+
